"""Extract the T1-free terms from the pinned pdaggerq CCSDT example.

Invoke with the source example and a destination path. The source is
https://github.com/edeprince3/pdaggerq/blob/7676be740eebeeba9735da8bcd9c3715aa40159b/examples/full_cc_codes/ccsdt.py
See LICENSE.pdaggerq. Original permutations are expressed as array views.
"""

import argparse
import ast
from pathlib import Path
import re


def generate(source):
    lines = [
        '"""T1-dressed residual contractions adapted from pdaggerq (Apache-2.0).',
        '',
        'Generated by tools/generate_equations.py. See THIRD_PARTY.md.',
        '"""',
        '',
        'from numpy import einsum',
        '',
    ]
    for rank, name in enumerate(("singles", "doubles", "triples"), start=1):
        node = next(node for node in ast.parse(source).body
                    if isinstance(node, ast.FunctionDef) and node.name == name + "_residual")
        lines.extend(["", f"def {name}(f, g, t2, t3, ladder, einsum=einsum):"])
        result = name + "_res"
        skip = False
        for statement in node.body:
            if isinstance(statement, ast.Expr):
                continue  # The upstream docstring.
            if isinstance(statement, ast.Return):
                lines.append("    " + ast.unparse(statement))
                break
            expression = ast.unparse(statement.value)
            if expression.startswith("1.0 * contracted_intermediate"):
                if skip:
                    continue
                for call in reversed(list(ast.walk(statement.value))):
                    if not isinstance(call, ast.Call):
                        continue
                    original, permuted = call.args[0].value.split("->")
                    axes = tuple(original.index(index) for index in permuted)
                    expression = expression.replace(ast.unparse(call),
                                                    f"contracted_intermediate.transpose{axes}")
                for term in expression.split(" + "):
                    sign = "-=" if term.startswith("-") else "+="
                    view = term.split(" * ")[-1]
                    lines.append(f"{indent}{result} {sign} {view}")
                continue
            skip = any(isinstance(child, ast.Name) and child.id == "t1"
                       for child in ast.walk(statement.value))
            if skip:
                continue
            target = statement.targets[0].id if isinstance(statement, ast.Assign) else statement.target.id
            if target == result and not any(line.startswith(f"    {result} =") for line in lines):
                shape = ("f['vo']", "g['vvoo']", "t3")[rank - 1]
                lines.append(f"    {result} = {shape}.copy()")
                if rank < 3:
                    if rank == 1:
                        continue
                    lines[-1] = f"    {result} = {shape} * 0.0"
            if target == "contracted_intermediate" and not any(
                line.startswith(f"    {result} =") for line in lines
            ):
                shape = ("f['vo']", "g['vvoo']", "t3")[rank - 1]
                lines.append(f"    {result} = {shape} * 0.0")
            indent = "    "
            if rank < 3 and re.search(r"\bt3\b", expression):
                lines.append("    if t3 is not None:")
                indent += "    "
            expression = re.sub(r"([fg])\[([ov, ]+)\]",
                                lambda match: f"{match[1]}['{match[2].replace(',', '').replace(' ', '')}']",
                                expression)
            if expression.startswith("0.5 * einsum('abcd,cdij") or expression.startswith(
                "0.5 * einsum('abde,decijk"
            ):
                expression = f"ladder(g['vvvv'], t{rank})"
            elif "optimize=" not in expression and "einsum(" in expression:
                if "," in expression.split("->")[0].split("'")[-1]:
                    expression = expression[:-1] + ", optimize=True)"
            operation = "=" if target == "contracted_intermediate" else "+="
            lines.append(f"{indent}{target} {operation} {expression}")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("upstream", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    args.output.write_text(generate(args.upstream.read_text(encoding="utf-8")), encoding="utf-8")

